'use strict';

// MODULES //

var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// FUNCTIONS //

/**
* Validates scalar selectors and the order before examining buffers.
* @private
* @param {string} uplo - triangle
* @param {string} way - conversion direction
* @param {NonNegativeInteger} N - order
* @throws {TypeError} invalid selectors
* @throws {RangeError} invalid order
* @returns {Array} normalized selector enums
*/
function scalars( uplo, way, N ) {
	if ( uplo !== 'upper' && uplo !== 'lower' ) {
		throw new TypeError( 'invalid argument. Triangle must be upper or lower.' );
	}
	if ( way !== 'convert' && way !== 'revert' ) {
		throw new TypeError( 'invalid argument. Direction must be convert or revert.' );
	}
	if ( !isSafeInteger( N ) || N < 0 || N > 2147483647 ) {
		throw new RangeError( 'invalid argument. Order must be a nonnegative signed32 integer.' );
	}
	return [ (uplo === 'upper') ? 121 : 122, (way === 'convert') ? 67 : 82 ];
}


// MAIN //

/**
* Creates the proposed public main and alternative-indexing interfaces.
* @private
* @param {Function} base - validated normalized kernel
* @returns {Function} public interfaces
*/
function factory( base ) {
	setReadOnly( dsyconvfRook, 'ndarray', ndarray );
	return dsyconvfRook;

	/**
	* Converts or reverts symmetric indefinite rook factor storage.
	* @private
	* @param {string} order - storage layout
	* @param {string} uplo - stored triangle
	* @param {string} way - convert or revert
	* @param {NonNegativeInteger} N - order
	* @param {Float64Array} A - factor matrix
	* @param {PositiveInteger} LDA - leading dimension
	* @param {Float64Array} E - off-diagonal storage
	* @param {Int32Array} IPIV - signed one-based rook pivots
	* @throws {TypeError} invalid selectors or buffers
	* @throws {RangeError} invalid metadata or pivots
	* @returns {integer} zero success status
	*/
	function dsyconvfRook( order, uplo, way, N, A, LDA, E, IPIV ) { // eslint-disable-line max-params
		var sa1;
		var sa2;
		var s;
		if ( order !== 'row-major' && order !== 'column-major' ) {
			throw new TypeError( 'invalid argument. Order must be row-major or column-major.' );
		}
		s = scalars( uplo, way, N );
		if ( !isSafeInteger( LDA ) || LDA < 1 || LDA < N ) {
			throw new RangeError( 'invalid argument. Leading dimension must be a safe integer at least max(1,N).' );
		}
		if ( N === 0 ) {
			return 0;
		}
		sa1 = (order === 'column-major') ? 1 : LDA;
		sa2 = (order === 'column-major') ? LDA : 1;
		validate( s[0], s[1], N, A, sa1, sa2, 0, E, 1, 0, IPIV, 1, 0 );
		return base( s[0], s[1], N, A, sa1, sa2, 0, E, 1, 0, IPIV, 1, 0 );
	}

	/**
	* Converts or reverts factor storage using independent indexing strides.
	* @private
	* @param {string} uplo - stored triangle
	* @param {string} way - convert or revert
	* @param {NonNegativeInteger} N - order
	* @param {Float64Array} A - factor matrix
	* @param {integer} sa1 - row stride
	* @param {integer} sa2 - column stride
	* @param {integer} oa - matrix offset
	* @param {Float64Array} E - off-diagonal storage
	* @param {integer} se - storage stride
	* @param {integer} oe - storage offset
	* @param {Int32Array} P - signed one-based rook pivots
	* @param {integer} sp - pivot stride
	* @param {integer} op - pivot offset
	* @throws {TypeError} invalid selectors or buffers
	* @throws {RangeError} invalid metadata or pivots
	* @returns {integer} zero success status
	*/
	function ndarray( uplo, way, N, A, sa1, sa2, oa, E, se, oe, P, sp, op ) { // eslint-disable-line max-params
		var s;
		s = scalars( uplo, way, N );
		if ( N === 0 ) {
			return 0;
		}
		validate( s[0], s[1], N, A, sa1, sa2, oa, E, se, oe, P, sp, op );
		return base( s[0], s[1], N, A, sa1, sa2, oa, E, se, oe, P, sp, op );
	}
}

module.exports = factory;
